self.addEventListener("push", (event) => {
  const payload = pushPayload(event)

  event.waitUntil(self.registration.showNotification(payload.title || "Fizzy", {
    body: payload.body,
    data: { url: payload.url },
    icon: "/app-icon-192.png",
    tag: payload.url
  }))
})

self.addEventListener("notificationclick", (event) => {
  event.notification.close()

  const url = sameOriginUrl(event.notification.data?.url)
  if (url) event.waitUntil(openWindow(url))
})

function pushPayload(event) {
  try {
    return event.data?.json() || {}
  } catch (error) {
    return {}
  }
}

function sameOriginUrl(value) {
  try {
    const url = new URL(value, self.location.origin)
    return url.origin === self.location.origin ? url.href : null
  } catch (error) {
    return null
  }
}

async function openWindow(url) {
  const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true })
  const matchingWindow = windows.find(client => client.url === url)

  if (matchingWindow) return matchingWindow.focus()

  const existingWindow = windows[0]
  if (existingWindow?.navigate) {
    await existingWindow.navigate(url)
    return existingWindow.focus()
  }

  return self.clients.openWindow(url)
}
